{
  "interpretation": {
    "name": "CalibrateSharedNutrunnerBeforeLine2Use",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Calibrate the shared nutrunner NR7 before line 2 uses it to tighten the F30 variant fasteners at st2.",
    "constraints": [
      "Calibration of NR7 must be completed before NR7 is configured or used for tightening on line 2",
      "NR7 must be reserved exclusively for line 2 for the whole use, and the reservation must be released at the end",
